def infix_to_postfix(expression: str) -> str:
    prec = {'^': 3, '*': 2, '/': 2, '+': 1, '-': 1}
    out, stack = [], []
    for ch in expression:
        if ch.isalnum():
            out.append(ch)
        elif ch == '(':
            stack.append(ch)
        elif ch == ')':
            while stack and stack[-1] != '(':
                out.append(stack.pop())
            stack.pop()  # discard '('
        else:
            while stack and stack[-1] != '(' and prec[stack[-1]] >= prec[ch]:
                out.append(stack.pop())
            stack.append(ch)
    while stack:
        out.append(stack.pop())
    return ''.join(out)

