#include <bits/stdc++.h>
using namespace std;

string infixToPostfix(string s) {
    unordered_map<char, int> prec{{'^', 3}, {'*', 2}, {'/', 2}, {'+', 1}, {'-', 1}};
    string ans;
    stack<char> st;
    for (char c : s) {
        if (isalnum((unsigned char)c)) ans.push_back(c);
        else if (c == '(') st.push(c);
        else if (c == ')') {
            while (!st.empty() && st.top() != '(') { ans.push_back(st.top()); st.pop(); }
            st.pop();
        } else {
            while (!st.empty() && st.top() != '(' && prec[st.top()] >= prec[c]) {
                ans.push_back(st.top()); st.pop();
            }
            st.push(c);
        }
    }
    while (!st.empty()) { ans.push_back(st.top()); st.pop(); }
    return ans;
}

